use xiom.io;
fn generate_fibonacci(count: Int) -> Vec[Int] {
  var fibs: Vec[Int] = Vec[Int].new();
  if count >= 1 { fibs.push(0); };
  if count >= 2 { fibs.push(1); };
  var i = 2;
  while i < count {
    let a = fibs.get(i - 2).unwrap();
    let b = fibs.get(i - 1).unwrap();
    fibs.push(a + b);
    i += 1;
  };
  fibs
}

fn main() -> Int {
  let fibs = generate_fibonacci(20);
  var i = 0;
  while i < fibs.len() {
    io.println(fibs.get(i).unwrap().to_str());
    i += 1;
  };
  return 0;
}
